'use strict';

// MODULES //

var tape = require( 'tape' );
var toAccessorArray = require( '@stdlib/array/base/to-accessor-array' );
var gindexOfGreaterThanSorted = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gindexOfGreaterThanSorted, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 5', function test( t ) {
	t.strictEqual( gindexOfGreaterThanSorted.length, 5, 'has expected arity' );
	t.end();
});

tape( 'the function returns the index of the first element in a sorted array which is greater than a search element', function test( t ) {
	var actual;
	var x;

	x = [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ];

	// Nonnegative stride...
	actual = gindexOfGreaterThanSorted( x.length, 0.0, x, 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length, 1.0, x, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length, 1.5, x, 1, 0 );
	t.strictEqual( actual, 2, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length, 2.0, x, 1, 0 );
	t.strictEqual( actual, 4, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length-1, 1.0, x, 1, 1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length-2, 2.0, x, 1, 2 );
	t.strictEqual( actual, 2, 'returns expected value' );

	// Negative stride...
	x = [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ];

	actual = gindexOfGreaterThanSorted( x.length, 0.0, x, -1, x.length-1 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length, 1.0, x, -1, x.length-1 );
	t.strictEqual( actual, 2, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length, 2.0, x, -1, x.length-1 );
	t.strictEqual( actual, 4, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( 3, 1.0, x, -2, x.length-1 );
	t.strictEqual( actual, 1, 'returns expected value' );

	t.end();
});

