tape( 'the function returns `N` if all elements are less than or equal to a search element', function test( t ) {
	var actual;
	var x;

	x = [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ];

	// Nonnegative stride...
	actual = gindexOfGreaterThanSorted( x.length, 3.0, x, 1, 0 );
	t.strictEqual( actual, x.length, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( x.length, 4.0, x, 1, 0 );
	t.strictEqual( actual, x.length, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( 1, 1.0, x, 1, 0 );
	t.strictEqual( actual, 1, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( 3, 2.0, x, 1, 0 );
	t.strictEqual( actual, 3, 'returns expected value' );

	// Negative stride...
	x = [ 3.0, 3.0, 2.0, 2.0, 1.0, 1.0 ];

	actual = gindexOfGreaterThanSorted( x.length, 3.0, x, -1, x.length-1 );
	t.strictEqual( actual, x.length, 'returns expected value' );

	t.end();
});

