tape( 'the function returns `0` if provided an `N` parameter which is less than or equal to zero', function test( t ) {
	var actual;

	actual = gindexOfGreaterThanSorted( 0, 2.0, [ 1.0, 2.0, 3.0 ], 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	actual = gindexOfGreaterThanSorted( -1, 2.0, [ 1.0, 2.0, 3.0 ], 1, 0 );
	t.strictEqual( actual, 0, 'returns expected value' );

	t.end();
});

